// Vendored from the Agentic Owners policy core; see README.md in this
// directory.

import type { AgenticOwnersPolicyMode } from "./policyMode.js";

export type AgenticOwnersPathRule = {
  readonly sourcePath: string;
  readonly scopeDepth: number;
  /**
   * True for the synthetic rule produced by root-level `global_exclusions`.
   * Global exclusions win before normal directory-depth precedence and carry
   * no owners, so they never enroll a review.
   */
  readonly globalExclusion?: boolean;
  /**
   * True for a root `global_overrides` entry. These rules are not precedence
   * candidates. After a file's winning rule is chosen, a matching override
   * adds its owners to an advisory winner, or becomes the owner when no
   * committed rule owns the file. `self_review` on the override applies to
   * the override's owners either way, and does not extend to the existing
   * winner's owners. Exclusions, always-approve, hard, and notify winners
   * stay unchanged, as do winners owned by a `skip_teams` team and paths
   * listed in `skip_paths`.
   */
  readonly globalOverride?: boolean;
  /**
   * Glob patterns relative to the directory containing `.agentic-owners`.
   * Root-policy paths are relative to the repository root.
   * Leading `../` segments may address sibling trees but cannot leave the repo.
   */
  readonly paths: readonly string[];
  /** Teams whose winning rule a `global_overrides` entry must not change. */
  readonly skipTeams?: readonly string[];
  /** Paths a `global_overrides` entry must not change. */
  readonly skipPaths?: readonly string[];
  /**
   * Team slugs (or `org/team` handles) that own these paths. A policy may
   * list more than one. `team` is the first entry, kept for convenience.
   */
  readonly teams: readonly string[];
  /** GitHub user handles (no `@`) that own these paths. `user` is the first. */
  readonly users: readonly string[];
  /** Primary (first) team owner, or undefined when there are none. */
  readonly team?: string;
  /** Primary (first) user owner, or undefined when there are none. */
  readonly user?: string;
  /** Filename of a prompt file in the same directory as policy.yml. */
  readonly prompt?: string;
  /**
   * True when this rule is satisfied regardless of the model's risk verdict.
   * Always-approved rules carry no owners or review instructions.
   */
  readonly alwaysApprove: boolean;
  readonly mode: AgenticOwnersPolicyMode;
  readonly humanReviewRequired: boolean;
  readonly selfReview: boolean;
  /**
   * Owners who may use {@link selfReview}. Absent means every owner on the
   * rule. A merged override lists the winner's owners when that rule sets
   * `self_review`, and the override's owners when the override sets it.
   */
  readonly selfReviewTeams?: readonly string[];
  /** User owners who may use {@link selfReview}. See {@link selfReviewTeams}. */
  readonly selfReviewUsers?: readonly string[];
};

export type AgenticOwnersRepoConfig = {
  readonly rules: readonly AgenticOwnersPathRule[];
};

export type AgenticOwnersMatchedConfig = {
  readonly matchedRules: readonly AgenticOwnersPathRule[];
};
